from django.db import models


class Resume(models.Model):
    """Stores the resume JSON generated by the frontend and saved by the user."""

    owner_email = models.EmailField(max_length=255)
    template_name = models.CharField(max_length=80, blank=True, default="techModern")
    resume_data = models.JSONField(default=dict)
    created_at = models.DateTimeField(auto_now_add=True)
    updated_at = models.DateTimeField(auto_now=True)

    class Meta:
        ordering = ["-updated_at"]

    def __str__(self):
        return f"{self.owner_email} - {self.template_name}"


class ResumeAnalysisCache(models.Model):
    """Stores short-lived ATS results without retaining the source resume."""

    content_hash = models.CharField(max_length=64, unique=True)
    result = models.JSONField()
    created_at = models.DateTimeField(auto_now_add=True)
    expires_at = models.DateTimeField(db_index=True)

    class Meta:
        ordering = ["-created_at"]

    def __str__(self):
        return f"ATS analysis cache entry {self.content_hash[:12]}"
